Yes. It can be done by adding the following to a project, however it'd be a nice-to-have as a built-in. There may be issues I haven't considered with adding it as a core feature, so if that's the case, this at least should be helpful for those who might like it in their project. Keep in mind it assumes you're not modifying the collection as you're iterating.

```cs
public static class NodeExtensions
{
    public static NodeEnumerable<Node> GetEnumerable(this Node node)
    {
        return new NodeEnumerable<Node>(node);
    }

    public static NodeEnumerable<T> GetEnumerable<T>(this Node node) where T : Node
    {
        return new NodeEnumerable<T>(node);
    }
}

public struct NodeEnumerator<T> where T : Node
{
    private readonly int _count;
    private readonly Node _node;
    private int _index;
    private T _next = null!;

    public NodeEnumerator(Node node)
    {
        _node = node;
        _count = _node.GetChildCount();
        _index = -1;
    }

    public readonly T Current => _next;

    public bool MoveNext()
    {
        while (++_index < _count)
        {
            if (_node.GetChild(_index) is T child)
            {
                _next = child;
                return true;
            }
        }

        return false;
    }

    public void Reset()
    {
        _index = -1;
        _next = null!;
    }
}

public readonly struct NodeEnumerable<T>(Node node) where T : Node
{
    private readonly Node _node = node;
    public readonly NodeEnumerator<T> GetEnumerator() => new(_node);
}
